gmW(){return"Turnitin\uc740 \uae30\uad00 \uad6c\ub9e4\ub9cc \uac00\ub2a5\ud558\uc5ec \uac1c\uc778\uc774 \uc9c1\uc811 \uad6c\ub9e4\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. TruthLens\ub294 \ub204\uad6c\ub098 \uc124\uce58\ud558\uc5ec \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."},
gmX(){return"Turnitin\uc758 \ud310\uc815 \uacfc\uc815\uc740 \ube14\ub799\ubc15\uc2a4\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4. TruthLens\ub294 \ubb38\uc7a5\ubcc4 AI \ud655\ub960, \uc77c\uce58\ud558\ub294 \ubb38\uccb4 \ud328\ud134, 4\uac1c \uc5d4\uc9c4 \uac01\uac01\uc758 \uc810\uc218\uc640 \uadfc\uac70\ub97c \uc0c1\uc138\ud788 \uc81c\uacf5\ud569\ub2c8\ub2e4."},
gmY(){return'Turnitin\uc740 \uc8fc\ub85c "AI \uc5ec\ubd80"\uc5d0 \ub300\ud55c \uc774\uc9c4 \ud310\uc815\uc785\ub2c8\ub2e4. TruthLens\ub294 \ub2e8\ub77d/\ubb38\uc7a5 \ub2e8\uc704\ub85c \uc0ac\ub78c\uff0fAI\uff0f\ud63c\ud569 \ud45c\uc2dc\ub97c \uc9c0\uc6d0\ud569\ub2c8\ub2e4.'},
